package com.campusradar.application;

import com.campusradar.catalog.JobsController;
import com.campusradar.common.ApiProblem;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.json.JsonMapper;

@Service
@Transactional
public class ApplicationService {
    public static final List<String> STAGES=List.of("PENDING","APPLIED","ASSESSMENT","INTERVIEW_1","INTERVIEW_2","HR","OFFER","CLOSED");
    private static final Set<String> REASONS=Set.of("REJECTED","WITHDRAWN","EXPIRED","ACCEPTED","OTHER");
    private static final BigDecimal STEP=new BigDecimal("1024"), MIN_GAP=new BigDecimal("0.0000000001");
    private final NamedParameterJdbcTemplate db; private final JsonMapper json; private final JobsController jobs; private final Clock clock;
    public ApplicationService(NamedParameterJdbcTemplate db,JsonMapper json,JobsController jobs,Clock clock){this.db=db;this.json=json;this.jobs=jobs;this.clock=clock;}
    public static Map<String,Object> map(Object... pairs){var m=new LinkedHashMap<String,Object>();for(int i=0;i<pairs.length;i+=2)m.put((String)pairs[i],pairs[i+1]);return m;}
    private List<Map<String,Object>> rows(String sql,Map<String,?> p){return db.query(sql,p,(r,n)->{var m=new LinkedHashMap<String,Object>();for(int i=1;i<=r.getMetaData().getColumnCount();i++)m.put(r.getMetaData().getColumnLabel(i).toLowerCase(Locale.ROOT),r.getObject(i));return m;});}
    private long count(String sql,Map<String,?> p){return db.queryForObject(sql,p,Long.class);}
    private static String iso(Object value){if(value==null)return null;if(value instanceof Timestamp t)return t.toInstant().toString();if(value instanceof LocalDateTime t)return t.toInstant(ZoneOffset.UTC).toString();return value.toString();}
    private static Timestamp timestamp(Object value){return value==null?null:Timestamp.from(Instant.parse(iso(value)));}
    private static int number(Object value){return ((Number)value).intValue();}
    private static void invalid(){throw new ApiProblem(422,"VALIDATION_ERROR","请求字段或取值无效。");}
    public static void uuid(String value){try{if(value==null || !UUID.fromString(value).toString().equalsIgnoreCase(value))invalid();}catch(IllegalArgumentException e){invalid();}}
    private static void fields(Map<String,Object> body,Set<String> allowed,Set<String> required){if(!allowed.containsAll(body.keySet()) || !body.keySet().containsAll(required))invalid();}
    private static int version(Map<String,Object> b,String field){Object v=b.get(field);if(!(v instanceof Number n)||n.doubleValue()!=n.intValue()||n.intValue()<1)invalid();return ((Number)v).intValue();}
    private static String text(Map<String,Object> b,String field,boolean nullable,int max){Object v=b.get(field);if(v==null){if(!nullable)invalid();return null;}if(!(v instanceof String s)||s.length()>max)invalid();return (String)v;}
    private static String idValue(Map<String,Object> b,String key){String id=text(b,key,true,36);if(id!=null)uuid(id);return id;}
    private Map<String,Object> user(String user,boolean write){var list=rows("SELECT id,status,data_operation,board_version FROM users WHERE id=:u FOR UPDATE",Map.of("u",user));if(list.isEmpty())throw new ApiProblem(401,"UNAUTHENTICATED","请先登录。");var row=list.getFirst();if(!"ACTIVE".equals(row.get("status")))throw new ApiProblem(403,"ACCOUNT_INACTIVE","账号当前不可用。");if(write&&!"IDLE".equals(row.get("data_operation")))throw new ApiProblem(409,"DATA_OPERATION_IN_PROGRESS","账号正在处理数据，请稍后重试。");return row;}
    private Map<String,Object> raw(String owner,String id){uuid(id);var list=rows("SELECT * FROM applications WHERE user_id=:u AND id=:id",Map.of("u",owner,"id",id));if(list.isEmpty())throw new ApiProblem(404,"NOT_FOUND","投递不存在。");return list.getFirst();}
    private Map<String,Object> dto(Map<String,Object> a){return map("id",a.get("id"),"version",a.get("version"),"createdAt",iso(a.get("created_at")),"updatedAt",iso(a.get("updated_at")),"job",jobs.applicationJob((String)a.get("job_id")),"stage",a.get("stage"),"sortKey",((BigDecimal)a.get("sort_key")).toPlainString(),"notes",a.get("notes"),"resumeId",a.get("resume_id"),"appliedAt",iso(a.get("applied_at")),"closedReason",a.get("closed_reason"),"archivedAt",iso(a.get("archived_at")));}
    public Map<String,Object> detail(String owner,String id){user(owner,false);return dto(raw(owner,id));}
    private void resume(String owner,String id){if(id==null)return;uuid(id);if(count("SELECT COUNT(*) FROM resumes WHERE user_id=:u AND id=:id",Map.of("u",owner,"id",id))!=1)throw new ApiProblem(404,"NOT_FOUND","简历不存在。");}
    private Map<String,Object> changed(String owner,String id,int board,String operation){return map("application",dto(raw(owner,id)),"boardVersion",board,"operationId",operation);}
    private void revise(String owner,boolean board){db.update("UPDATE users SET data_revision=data_revision+1"+(board?",board_version=board_version+1":"")+" WHERE id=:u",Map.of("u",owner));}
    private static void expected(Map<String,Object> a,Map<String,Object> b,int board,boolean boardRequired){if(number(a.get("version"))!=version(b,"version"))throw new ApiProblem(409,"VERSION_CONFLICT","投递已更新，请刷新后重试。");if(boardRequired&&board!=version(b,"boardVersion"))throw new ApiProblem(409,"BOARD_VERSION_CONFLICT","看板已更新，请刷新后重试。");}
    private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    private Object canonical(Object v){if(v instanceof Map<?,?> m){var sorted=new TreeMap<String,Object>();m.forEach((k,x)->sorted.put(k.toString(),canonical(x)));return sorted;}if(v instanceof List<?> l)return l.stream().map(this::canonical).toList();return v;}
    @SuppressWarnings("unchecked") private Map<String,Object> idempotent(String owner,String path,String key,Map<String,Object> body,Supplier<Map<String,Object>> work){
        if(key==null||key.length()<16||key.length()>80)invalid();String route=hash(path),request=hash(json.writeValueAsString(canonical(body)));var p=map("u",owner,"route",route,"key",key);
        var existing=rows("SELECT request_hash,response_body,expires_at FROM idempotency_records WHERE user_id=:u AND method='POST' AND route_hash=:route AND idem_key=:key",p);
        if(!existing.isEmpty()) {var old=existing.getFirst();if(Instant.parse(iso(old.get("expires_at"))).isAfter(Instant.now(clock))){if(!request.equals(old.get("request_hash")))throw new ApiProblem(409,"IDEMPOTENCY_CONFLICT","相同请求键不能用于不同内容。");return json.readValue((old.get("response_body") instanceof byte[] bytes?new String(bytes,StandardCharsets.UTF_8):old.get("response_body").toString()),Map.class);}db.update("DELETE FROM idempotency_records WHERE user_id=:u AND method='POST' AND route_hash=:route AND idem_key=:key",p);}
        var result=(Map<String,Object>)json.readValue(json.writeValueAsString(work.get()),Map.class);p.put("id",UUID.randomUUID().toString());p.put("hash",request);p.put("body",json.writeValueAsString(result));p.put("expires",Timestamp.from(Instant.now(clock).plus(Duration.ofHours(24))));
        db.update("INSERT INTO idempotency_records(id,user_id,method,route_hash,idem_key,request_hash,http_status,response_body,expires_at) VALUES(:id,:u,'POST',:route,:key,:hash,200,:body,:expires)",p);return result;
    }
    public Map<String,Object> create(String owner,Map<String,Object> body,String key){
        fields(body,Set.of("jobId","resumeId"),Set.of("jobId"));String job=idValue(body,"jobId");if(job==null)invalid();String resume=idValue(body,"resumeId");int board=number(user(owner,true).get("board_version"));
        return idempotent(owner,"/api/v1/applications",key,body,()->{var prior=rows("SELECT * FROM applications WHERE user_id=:u AND job_id=:j",Map.of("u",owner,"j",job));if(!prior.isEmpty())return changed(owner,(String)prior.getFirst().get("id"),board,null);
            if(count("SELECT COUNT(*) FROM jobs j JOIN sources s ON s.id=j.source_id WHERE j.id=:id AND j.publication_status='PUBLISHED' AND s.enabled=1",Map.of("id",job))!=1)throw new ApiProblem(404,"NOT_FOUND","岗位不存在或不可用。");resume(owner,resume);
            BigDecimal sort=tail(owner,"PENDING");String id=UUID.randomUUID().toString();var p=map("u",owner,"id",id,"j",job,"resume",resume,"sort",sort);
            db.update("INSERT INTO applications(id,user_id,job_id,resume_id,stage,sort_key,notes) VALUES(:id,:u,:j,:resume,'PENDING',:sort,'')",p);event(owner,map("id",id,"stage",null,"sort_key",null),"PENDING",sort,new Position(null,null,sort),1,board+1,false);revise(owner,true);return changed(owner,id,board+1,null);});
    }
    private String filters(Map<String,Object> p,String stage,String company,Boolean archived){String where=" WHERE a.user_id=:u";if(stage!=null){if(!STAGES.contains(stage))invalid();where+=" AND a.stage=:stage";p.put("stage",stage);}if(company!=null){uuid(company);where+=" AND j.company_id=:company";p.put("company",company);}if(archived!=null)where+=archived?" AND a.archived_at IS NOT NULL":" AND a.archived_at IS NULL";return where;}
    public Map<String,Object> board(String owner,String stage,String company){int board=number(user(owner,false).get("board_version"));var p=map("u",owner);String where=filters(p,stage,company,false);var all=rows("SELECT a.* FROM applications a JOIN jobs j ON j.id=a.job_id"+where+" ORDER BY a.stage,a.sort_key,a.id LIMIT 501",p);var stats=rows("SELECT COUNT(*) total,SUM(CASE WHEN a.stage NOT IN ('PENDING','CLOSED') THEN 1 ELSE 0 END) applied,SUM(CASE WHEN a.stage IN ('INTERVIEW_1','INTERVIEW_2','HR') THEN 1 ELSE 0 END) interviewing,SUM(CASE WHEN a.stage='OFFER' THEN 1 ELSE 0 END) offers FROM applications a JOIN jobs j ON j.id=a.job_id"+where,p).getFirst();stats.replaceAll((k,v)->v==null?0:((Number)v).intValue());return map("items",all.stream().limit(500).map(this::dto).toList(),"boardVersion",board,"columns",STAGES,"stats",stats,"truncated",all.size()>500);}
    public Map<String,Object> list(String owner,int page,int size,String stage,String company,Boolean archived){page(page,size);user(owner,false);var p=map("u",owner,"limit",size,"offset",(page-1)*size);String where=filters(p,stage,company,archived);long total=count("SELECT COUNT(*) FROM applications a JOIN jobs j ON j.id=a.job_id"+where,p);var items=rows("SELECT a.* FROM applications a JOIN jobs j ON j.id=a.job_id"+where+" ORDER BY a.updated_at DESC,a.id LIMIT :limit OFFSET :offset",p).stream().map(this::dto).toList();return map("items",items,"total",total);}
    public static void page(int page,int size){if(page<1||page>500||size<1||size>100)invalid();}
    public Map<String,Object> patch(String owner,String id,Map<String,Object> body){fields(body,Set.of("version","notes","resumeId","appliedAt","archived"),Set.of("version"));if(body.size()<2)invalid();int board=number(user(owner,true).get("board_version"));var a=raw(owner,id);expected(a,body,board,false);var p=map("u",owner,"id",id,"version",version(body,"version"));String set="";
        if(body.containsKey("notes")){p.put("notes",text(body,"notes",false,20000));set+=",notes=:notes";}
        if(body.containsKey("resumeId")){String resume=idValue(body,"resumeId");resume(owner,resume);p.put("resume",resume);set+=",resume_id=:resume";}
        if(body.containsKey("appliedAt")){String value=text(body,"appliedAt",true,50);try{p.put("applied",value==null?null:Timestamp.from(Instant.parse(value)));}catch(DateTimeException e){invalid();}set+=",applied_at=:applied";}
        boolean boardChanged=false;if(body.containsKey("archived")){if(!(body.get("archived") instanceof Boolean))invalid();boolean archived=(Boolean)body.get("archived");boardChanged=archived!=(a.get("archived_at")!=null);p.put("archived",archived?Timestamp.from(Instant.now(clock)):null);set+=",archived_at=:archived";}
        int changed=db.update("UPDATE applications SET version=version+1,updated_at=CURRENT_TIMESTAMP"+set+" WHERE user_id=:u AND id=:id AND version=:version",p);if(changed!=1)throw new ApiProblem(409,"VERSION_CONFLICT","投递已更新。");revise(owner,boardChanged);return changed(owner,id,board+(boardChanged?1:0),null);
    }
    private List<Map<String,Object>> column(String owner,String stage,String exclude){return rows("SELECT id,sort_key,version FROM applications WHERE user_id=:u AND stage=:stage AND archived_at IS NULL AND id<>:exclude ORDER BY sort_key,id",Map.of("u",owner,"stage",stage,"exclude",exclude));}
    private BigDecimal tail(String owner,String stage){var a=column(owner,stage,"");return a.isEmpty()?STEP:((BigDecimal)a.getLast().get("sort_key")).add(STEP);}
    private record Position(String before,String after,BigDecimal sort){}
    private Position position(String owner,String stage,String moving,String before,String after,boolean strict){
        var all=column(owner,stage,moving);int beforeIndex=-1,afterIndex=-1;for(int i=0;i<all.size();i++){String id=(String)all.get(i).get("id");if(id.equals(before))beforeIndex=i;if(id.equals(after))afterIndex=i;}
        if((before!=null&&beforeIndex<0)||(after!=null&&afterIndex<0)||(before!=null&&after!=null&&afterIndex+1!=beforeIndex))throw new ApiProblem(409,"BOARD_NEIGHBOR_CONFLICT","目标列相邻卡片已变化，请刷新看板。");
        int index=before!=null?beforeIndex:after!=null?afterIndex+1:all.size();
        if(strict&&((before==null&&index!=all.size())||(after==null&&index!=0)))throw new ApiProblem(409,"UNDO_CONFLICT","原位置已变化，无法撤销。");
        BigDecimal low=index==0?null:(BigDecimal)all.get(index-1).get("sort_key"), high=index==all.size()?null:(BigDecimal)all.get(index).get("sort_key");
        if(low!=null&&high!=null&&high.subtract(low).compareTo(MIN_GAP)<=0){for(int i=0;i<all.size();i++)db.update("UPDATE applications SET sort_key=:sort,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE user_id=:u AND id=:id",map("u",owner,"id",all.get(i).get("id"),"sort",STEP.multiply(BigDecimal.valueOf(i+1))));return position(owner,stage,moving,before,after,strict);}
        BigDecimal sort=low==null?(high==null?STEP:high.subtract(STEP)):high==null?low.add(STEP):low.add(high).divide(BigDecimal.valueOf(2),10,RoundingMode.HALF_UP);
        return new Position(index==all.size()?null:(String)all.get(index).get("id"),index==0?null:(String)all.get(index-1).get("id"),sort);
    }
    private Position oldPosition(String owner,Map<String,Object> a){var all=column(owner,(String)a.get("stage"),"");for(int i=0;i<all.size();i++)if(all.get(i).get("id").equals(a.get("id")))return new Position(i+1==all.size()?null:(String)all.get(i+1).get("id"),i==0?null:(String)all.get(i-1).get("id"),(BigDecimal)a.get("sort_key"));throw new ApiProblem(409,"APPLICATION_ARCHIVED","请先恢复归档投递。");}
    private Timestamp eventTime(String owner){var max=rows("SELECT MAX(occurred_at) latest FROM application_stage_events WHERE user_id=:u",Map.of("u",owner)).getFirst().get("latest");Instant now=Instant.now(clock).truncatedTo(java.time.temporal.ChronoUnit.MILLIS);if(max!=null&&!now.isAfter(Instant.parse(iso(max))))now=Instant.parse(iso(max)).plusMillis(1);return Timestamp.from(now);}
    private String event(String owner,Map<String,Object> old,String stage,BigDecimal sort,Position prior,int result,int board,boolean undone){String operation=UUID.randomUUID().toString();var p=map("id",UUID.randomUUID().toString(),"u",owner,"app",old.get("id"),"op",operation,"from",old.get("stage"),"to",stage,"old",old.get("sort_key"),"new",sort,"before",prior.before(),"after",prior.after(),"result",result,"board",board,"time",eventTime(owner),"undone",undone,"reason",old.get("closed_reason"),"closed",old.get("closed_at"),"applied",old.get("applied_at"));
        db.update("INSERT INTO application_stage_events(id,user_id,application_id,operation_id,from_stage,to_stage,old_sort_key,new_sort_key,old_before_id,old_after_id,result_version,result_board_version,occurred_at,undone,old_closed_reason,old_closed_at,old_applied_at) VALUES(:id,:u,:app,:op,:from,:to,:old,:new,:before,:after,:result,:board,:time,:undone,:reason,:closed,:applied)",p);return operation;}
    public Map<String,Object> move(String owner,String id,Map<String,Object> body,String key){fields(body,Set.of("version","boardVersion","stage","beforeId","afterId","closedReason"),Set.of("version","boardVersion","stage"));String stage=text(body,"stage",false,32);if(!STAGES.contains(stage))invalid();String before=idValue(body,"beforeId"),after=idValue(body,"afterId"),reason=text(body,"closedReason",true,32);if("CLOSED".equals(stage)?reason==null||!REASONS.contains(reason):reason!=null)invalid();int board=number(user(owner,true).get("board_version"));uuid(id);
        return idempotent(owner,"/api/v1/applications/"+id+"/move",key,body,()->{var a=raw(owner,id);expected(a,body,board,true);var old=oldPosition(owner,a);Position target=position(owner,stage,id,before,after,false);var p=map("u",owner,"id",id,"version",version(body,"version"),"stage",stage,"sort",target.sort(),"reason",reason,"closed",stage.equals("CLOSED")?Timestamp.from(Instant.now(clock)):null,"applied",a.get("applied_at")==null&&!stage.equals("PENDING")?Timestamp.from(Instant.now(clock)):a.get("applied_at"));
            if(db.update("UPDATE applications SET stage=:stage,sort_key=:sort,closed_reason=:reason,closed_at=:closed,applied_at=:applied,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE user_id=:u AND id=:id AND version=:version",p)!=1)throw new ApiProblem(409,"VERSION_CONFLICT","投递已更新。");
            String operation=event(owner,a,stage,target.sort(),old,version(body,"version")+1,board+1,false);revise(owner,true);return changed(owner,id,board+1,operation);});
    }
    public Map<String,Object> undo(String owner,String id,Map<String,Object> body,String key){fields(body,Set.of("version","boardVersion","operationId"),Set.of("version","boardVersion","operationId"));String operation=idValue(body,"operationId");if(operation==null)invalid();int board=number(user(owner,true).get("board_version"));uuid(id);
        return idempotent(owner,"/api/v1/applications/"+id+"/undo",key,body,()->{var a=raw(owner,id);expected(a,body,board,true);var latest=rows("SELECT * FROM application_stage_events WHERE user_id=:u AND undone=0 ORDER BY occurred_at DESC,id DESC LIMIT 1",Map.of("u",owner));if(latest.isEmpty())throw new ApiProblem(409,"UNDO_CONFLICT","没有可撤销操作。");var e=latest.getFirst();if(!operation.equals(e.get("operation_id"))||!id.equals(e.get("application_id"))||number(e.get("result_version"))!=version(body,"version")||number(e.get("result_board_version"))!=board||e.get("from_stage")==null||Instant.parse(iso(e.get("occurred_at"))).isBefore(Instant.now(clock).minus(Duration.ofMinutes(10))))throw new ApiProblem(409,"UNDO_CONFLICT","只能撤销十分钟内最近且未修改的操作。");
            var old=oldPosition(owner,a);String stage=(String)e.get("from_stage");Position target=position(owner,stage,id,(String)e.get("old_before_id"),(String)e.get("old_after_id"),true);
            var p=map("u",owner,"id",id,"version",version(body,"version"),"stage",stage,"sort",target.sort(),"reason",e.get("old_closed_reason"),"closed",e.get("old_closed_at"),"applied",e.get("old_applied_at"));
            if(db.update("UPDATE applications SET stage=:stage,sort_key=:sort,closed_reason=:reason,closed_at=:closed,applied_at=:applied,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE user_id=:u AND id=:id AND version=:version",p)!=1)throw new ApiProblem(409,"VERSION_CONFLICT","投递已更新。");db.update("UPDATE application_stage_events SET undone=1 WHERE user_id=:u AND operation_id=:op AND undone=0",Map.of("u",owner,"op",operation));String inverse=event(owner,a,stage,target.sort(),old,version(body,"version")+1,board+1,true);revise(owner,true);return changed(owner,id,board+1,inverse);});
    }
    public Map<String,Object> history(String owner,String id,int page,int size){page(page,size);user(owner,false);raw(owner,id);var p=map("u",owner,"id",id,"limit",size,"offset",(page-1)*size);long total=count("SELECT COUNT(*) FROM application_stage_events WHERE user_id=:u AND application_id=:id",p);var history=rows("SELECT * FROM application_stage_events WHERE user_id=:u AND application_id=:id ORDER BY occurred_at DESC,id DESC LIMIT :limit OFFSET :offset",p).stream().map(e->map("id",e.get("id"),"version",e.get("version"),"createdAt",iso(e.get("created_at")),"updatedAt",iso(e.get("updated_at")),"applicationId",e.get("application_id"),"fromStage",e.get("from_stage"),"toStage",e.get("to_stage"),"operationId",e.get("operation_id"),"occurredAt",iso(e.get("occurred_at")),"actorId",owner)).toList();return map("items",history,"total",total);}
}
